        try {
            const { stdout } = await executeGit(rootPath, args);

            return stdout.trim();
        } catch (error) {
            if (!isGitIndexLockError(error)) throw error;
            console.warn('[git:index-lock-retry]', {
                args,
                cwd: rootPath,
                delayMs: retryDelay,
                retry: retryIndex + 1,
            });
            await delay(retryDelay);
        }
    }

    try {
        const { stdout } = await executeGit(rootPath, args);

        return stdout.trim();
